const badge=(text,kind='')=>'<span class="badge '+kind+'">'+esc(text)+'</span>';
const statusKind=s=>/cerrado|rechazado|retirad/i.test(s)?'':/acept|gestión|public|dispon|verific/i.test(s)?'green':/pend|revisión|aclar/i.test(s)?'amber':'blue';
const now=()=>new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'});
const sectors=['Sector Central','Sector Norte','Sector Parque','Sector Enlace'];
const opts=(a,v)=>a.map(x=>'<option '+(x===v?'selected':'')+'>'+esc(x)+'</option>').join('');
